// same as https://github.com/alexarchambault/data-class/blob/cb28e25100090785fc6ae790a6cc9f6f79bb2043/src/main/scala/dataclass/data.scala
// but stripping the macros

package dataclass

import scala.annotation.{StaticAnnotation, compileTimeOnly}

/** Scala 3 stand-in for the data-class `@data` macro annotation, for sources shared with Scala 2
  *
  * A no-op: the annotated classes are case classes, and their binary-compatible `apply` / `copy` /
  * constructor overloads are generated by the unroll compiler plugin from the `@since` annotations
  * (see `modules/unroll` in the case-app repository). No setter is generated, so that the
  * parameters about those have no effect.
  */
@compileTimeOnly("enable macro paradise to expand macro annotations")
class data(
  apply: Boolean = true,
  publicConstructor: Boolean = true,
  optionSetters: Boolean = false,
  settersCallApply: Boolean = false,
  cachedHashCode: Boolean = false,
  deprecatedSetters: Boolean = false,
  deprecatedSettersMessage: String = "",
  deprecatedSettersSince: String = "",
  setters: Boolean = true
) extends StaticAnnotation {
  // former constructor, kept for binary compatibility
  def this(
    apply: Boolean,
    publicConstructor: Boolean,
    optionSetters: Boolean,
    settersCallApply: Boolean
  ) =
    this(apply, publicConstructor, optionSetters, settersCallApply, false, false, "", "", true)
}
